    "Address poisoning pattern — sender resembles recipient (matching prefix and suffix). Verify the full base58 address before sending funds.": "Подмена адреса (address poisoning) — отправитель похож на получателя (совпадение префикса и суффикса). Сверьте полный base58-адрес перед любым переводом.",
    "Micro TRX transfer ({amount} TRX) — typical dust/spam probe. Do not treat as payment and never copy an address from history without verifying every character.": "Микро-перевод TRX ({amount} TRX) — типичный dust/spam-зонд. Не считайте оплатой и не копируйте адрес из истории без проверки каждого символа.",
    "Possible dust attack — micro-transfer designed to pollute your transaction history.": "Возможная dust-атака — микро-перевод для засорения истории транзакций.",
    "Micro {symbol} transfer — suspicious dust amount on a non-official token. Verify the contract/asset ID before interacting.": "Микро-перевод {symbol} — подозрительная dust-сумма по неофициальному токену. Проверьте контракт/ID актива перед действиями.",
    "High-volume dust sender — mass outbound micro-transfers ({out} sent / {in} received). Likely spam probe or address-poisoning setup.": "Массовый dust-отправитель — много исходящих микро-переводов ({out} исх. / {in} вх.). Вероятен spam-зонд или подготовка address poisoning.",
