    "Upgradeable fiat-token proxy — standard Circle/Tether deployment pattern on TRON, not a scam indicator.": "Proxy fiat-token có thể nâng cấp — mẫu Circle/Tether chuẩn trên TRON, không phải lừa đảo.",
    "Upgradeable proxy pattern — owner can silently replace contract logic at any time.": "Mẫu proxy có thể nâng cấp — chủ sở hữu có thể thay logic im lặng.",
    "Very few ABI entries — possible minimal proxy. Real logic may be elsewhere.": "Rất ít mục ABI — có thể là minimal proxy. Logic thật có thể ở nơi khác.",
    "Wallet drainer — \"connect wallet\" lure": "Wallet drainer — mồi «connect wallet»",
    "WalletConnect phishing on suspicious TLD": "Phishing WalletConnect trên TLD đáng ngờ",
