    "batch burn function — owner can destroy tokens from any address if not restricted.": "Hàm batch burn — chủ sở hữu có thể đốt token từ mọi địa chỉ nếu không bị hạn chế.",
    "claim + multicall + owner change — classic asset-split drain. Do not approve or call any function.": "claim + multicall + owner change — drain asset-split kinh điển. Không approve hoặc gọi hàm nào.",
    "claim() + multicall() on a non-standard contract — may batch-split your token balance to attacker wallets.": "claim() + multicall() trên hợp đồng không chuẩn — có thể chia số dư sang ví tấn công.",
    "claim() on a non-standard contract — may pull approved tokens or TRX from your wallet to the owner.": "claim() trên hợp đồng không chuẩn — có thể kéo token đã approve hoặc TRX về chủ sở hữu.",
    "pause()/stop() present — owner can freeze all transfers without consent.": "Có pause()/stop() — chủ sở hữu có thể đóng băng mọi chuyển khoản.",
    "renounceOwnership() present — owner CAN give up control (check if already called).": "Có renounceOwnership() — chủ sở hữu CÓ THỂ từ bỏ quyền kiểm soát (kiểm tra đã gọi chưa).",
    "selfdestruct/destroy detected — owner can permanently kill the contract and lock all funds.": "Phát hiện selfdestruct/destroy — chủ sở hữu có thể hủy hợp đồng và khóa tiền.",
    "setFee/tax function found — owner can change fees/taxes at will.": "Có hàm setFee/tax — chủ sở hữu có thể đổi phí/thuế tùy ý.",
    "transferOwnership() present — control can be transferred silently.": "Có transferOwnership() — quyền kiểm soát có thể chuyển im lặng.",
